)

SELECT p.post_id AS postId, p.title, u.name AS authorName, p.view_count AS viewCount, p.is_pinned AS isPinned, p.created_at AS created, c.name AS categoryName, EXISTS (SELECT 1 FROM attachments a WHERE a.post_id = p.post_id) AS hasAttachment, (SELECT COUNT(*) FROM comments cm WHERE cm.post_id = p.post_id AND cm.state = 'normal') AS commentCount, (SELECT COUNT(*) FROM post_likes pl WHERE pl.post_id = p.post_id) AS likeCount FROM posts p INNER JOIN users u ON p.user_id = u.user_id LEFT JOIN categories c ON p.category_id = c.category_id WHERE p.board_id = #{boardId} AND p.state = 'normal'
AND p.category_id = #{categoryId}
AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.is_pinned DESC,
p.view_count DESC p.created_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM posts
WHERE board_id = #{boardId}
  AND state = 'normal'

    AND category_id = #{categoryId}


    AND (title LIKE CONCAT('%', #{keyword}, '%') OR content LIKE CONCAT('%', #{keyword}, '%'))

